[8705] = {id=8705,name="Gavel of Infinite Wisdom",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=5695,description="The Qiraji and their servants wield items made with the rarest and finest materials: bones from gargantuan ancient creatures, gems from the depths of the earth, metals pure and strong. Just the sight of Qiraji artifacts fills me with an urge to practice my craft with their shattered and smelted pieces. Prove your allegiance to the Circle, , and I will make you a powerful weapon from the finest Qiraji materials.",starts={{npcID=15499,x=0.594,y=0.14,zoneID=5695}},ends={{npcID=15499,x=0.594,y=0.14,zoneID=5695}},coords={x=0.594,y=0.14,source="quest_giver",zoneID=5695},questType="raid"},
