[9250] = {id=9250,name="Frame of Atiesh",level=30,requiredLevel=30,faction="both",expansion=0,zoneID=440,mapID=71,description="With the frame formed, Atiesh is nearly whole. Only the head and base of the staff are now missing. There is also a minor issue regarding the staff being a conduit for Sargeras's evil. Find someone that can assist you in locating the remaining pieces and exorcising the evil from the staff.",questType="raid"},
